        "color=#%color",
        "combo#true,false",
        "default=%<default value%>",
        "disabled#true,false",
        "format={%<JavaScript code%>}",
        "height=##L",
        "hidden#true,false",
        "keystroke={%<JavaScript code%>}",
        "mappingname=%<name%>",
        "maxlen=%<number%>",
        "menulength=%<number%>",
        "multiline#true,false",
        "name=%<name%>",
        "onblur={%<JavaScript code%>}",
